-- 0.20.41 — Políticas operacionais persistentes + seed dos presets
PRAGMA foreign_keys = ON;

CREATE TABLE IF NOT EXISTS v2_project_policy_links (
  id TEXT PRIMARY KEY NOT NULL,
  project_id TEXT NOT NULL REFERENCES automatic_projects(id) ON DELETE CASCADE,
  policy_id TEXT NOT NULL REFERENCES operational_policies(id) ON DELETE CASCADE,
  active INTEGER NOT NULL DEFAULT 1,
  created_by TEXT,
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL,
  removed_at INTEGER
);
CREATE UNIQUE INDEX IF NOT EXISTS idx_v2_project_policy_link_unique ON v2_project_policy_links(project_id,policy_id);
CREATE INDEX IF NOT EXISTS idx_v2_project_policy_link_active ON v2_project_policy_links(project_id,active,updated_at DESC);

INSERT INTO operational_policies(id,policy_key,name,description,category,status,rule_type,scope_level,propagation_level,preset,condition_json,action_json,priority,confidence,created_by,version,notes,created_at,updated_at)
SELECT 'POL-SEED-3OP-4X3','PRESET_3_OPCOES_4X3','3 opções — imagem contextual 4:3','A imagem contextual principal deve funcionar em quadro 4:3. Imagens maiores podem ser cortadas. Evitar retrato vertical estreito, sujeito pequeno ou excesso de vazio. O crop não pode destruir o sujeito principal.','OPERATIONAL_CONTEXT','ACTIVE','PERSISTENT_CONTEXT_POLICY','PRESET',200,'3_OPCOES','{"target_id":"3_OPCOES"}','{"instruction":"A imagem contextual principal deve funcionar em quadro 4:3. Imagens maiores podem ser cortadas. Evitar retrato vertical estreito, sujeito pequeno ou excesso de vazio. O crop não pode destruir o sujeito principal.","metadata":{},"asset_requirement":"raster_4x3"}',50,100,'SYSTEM_SEED',1,'Seed operacional obrigatório dos presets',unixepoch('now')*1000,unixepoch('now')*1000
WHERE NOT EXISTS (SELECT 1 FROM operational_policies WHERE policy_key='PRESET_3_OPCOES_4X3' AND rule_type='PERSISTENT_CONTEXT_POLICY' AND status!='DELETED');

INSERT INTO operational_policies(id,policy_key,name,description,category,status,rule_type,scope_level,propagation_level,preset,condition_json,action_json,priority,confidence,created_by,version,notes,created_at,updated_at)
SELECT 'POL-SEED-3OP-RES','PRESET_3_OPCOES_RESULT_4X3','3 opções — resultado 4:3','Quando a etapa de resultado apresentar imagem, usar imagem de resultado compatível com 4:3, com boa ocupação do quadro.','OPERATIONAL_CONTEXT','ACTIVE','PERSISTENT_CONTEXT_POLICY','PRESET',200,'3_OPCOES','{"target_id":"3_OPCOES"}','{"instruction":"Quando a etapa de resultado apresentar imagem, usar imagem de resultado compatível com 4:3, com boa ocupação do quadro.","metadata":{},"asset_requirement":"result_4x3","applies_to":["IMAGEM_RESULTADO","RESULTADO","RESULT"]}',50,100,'SYSTEM_SEED',1,'Seed operacional obrigatório dos presets',unixepoch('now')*1000,unixepoch('now')*1000
WHERE NOT EXISTS (SELECT 1 FROM operational_policies WHERE policy_key='PRESET_3_OPCOES_RESULT_4X3' AND rule_type='PERSISTENT_CONTEXT_POLICY' AND status!='DELETED');

