SELECT 'POL-SEED-VF-4X3','PRESET_VF_4X3','Verdadeiro/Falso — contextual 4:3','A imagem contextual deve funcionar em 4:3. Pode cortar uma imagem maior. Evitar retrato estreito e composição com muito espaço vazio.','OPERATIONAL_CONTEXT','ACTIVE','PERSISTENT_CONTEXT_POLICY','PRESET',200,'VERDADEIRO_FALSO','{"target_id":"VERDADEIRO_FALSO"}','{"instruction":"A imagem contextual deve funcionar em 4:3. Pode cortar uma imagem maior. Evitar retrato estreito e composição com muito espaço vazio.","metadata":{},"asset_requirement":"raster_4x3"}',50,100,'SYSTEM_SEED',1,'Seed operacional obrigatório dos presets',unixepoch('now')*1000,unixepoch('now')*1000
WHERE NOT EXISTS (SELECT 1 FROM operational_policies WHERE policy_key='PRESET_VF_4X3' AND rule_type='PERSISTENT_CONTEXT_POLICY' AND status!='DELETED');

