SELECT 'POL-SEED-PREF-4X3','PRESET_PREFERE_4X3','Qual você prefere — imagens A/B 4:3','As duas imagens A/B devem funcionar em cards 4:3. Podem ser cortadas a partir de imagens maiores. Evitar retratos estreitos, sujeitos pequenos e enquadramentos que criem grandes áreas vazias.','OPERATIONAL_CONTEXT','ACTIVE','PERSISTENT_CONTEXT_POLICY','PRESET',200,'QUAL_VOCE_PREFERE','{"target_id":"QUAL_VOCE_PREFERE"}','{"instruction":"As duas imagens A/B devem funcionar em cards 4:3. Podem ser cortadas a partir de imagens maiores. Evitar retratos estreitos, sujeitos pequenos e enquadramentos que criem grandes áreas vazias.","metadata":{},"asset_requirement":"raster_4x3","applies_to":["IMAGEM_A","IMAGEM_B"]}',50,100,'SYSTEM_SEED',1,'Seed operacional obrigatório dos presets',unixepoch('now')*1000,unixepoch('now')*1000
WHERE NOT EXISTS (SELECT 1 FROM operational_policies WHERE policy_key='PRESET_PREFERE_4X3' AND rule_type='PERSISTENT_CONTEXT_POLICY' AND status!='DELETED');

