SELECT 'POL-SEED-LOGO-4X3','PRESET_LOGO_4X3','Logo — área 4:3','A imagem usada pelo preset deve ser compatível com área 4:3. Imagens maiores podem ser cortadas desde que o logo/elemento principal permaneça inteiro e legível.','OPERATIONAL_CONTEXT','ACTIVE','PERSISTENT_CONTEXT_POLICY','PRESET',200,'LOGO','{"target_id":"LOGO"}','{"instruction":"A imagem usada pelo preset deve ser compatível com área 4:3. Imagens maiores podem ser cortadas desde que o logo/elemento principal permaneça inteiro e legível.","metadata":{},"asset_requirement":"raster_4x3"}',50,100,'SYSTEM_SEED',1,'Seed operacional obrigatório dos presets',unixepoch('now')*1000,unixepoch('now')*1000
