SELECT 'POL-SEED-LOGO-RES','PRESET_LOGO_RESULT_4X3','Logo resultado — 4:3','A imagem de revelação/resultado deve funcionar em 4:3 e manter o elemento principal legível.','OPERATIONAL_CONTEXT','ACTIVE','PERSISTENT_CONTEXT_POLICY','PRESET',200,'LOGO_RESULTADO','{"target_id":"LOGO_RESULTADO"}','{"instruction":"A imagem de revelação/resultado deve funcionar em 4:3 e manter o elemento principal legível.","metadata":{},"asset_requirement":"raster_4x3"}',50,100,'SYSTEM_SEED',1,'Seed operacional obrigatório dos presets',unixepoch('now')*1000,unixepoch('now')*1000
