SELECT 'POL-SEED-CENTRAL2','PRESET_CENTRAL_2_TRANSPARENT','Central + 2 exige transparência','A imagem principal central e as duas opções devem ser assets isolados com transparência real. Não usar cena contextual completa com fundo. Pode remover somente fundo simples quando a referência estiver correta. Não criar composição artificial.','OPERATIONAL_CONTEXT','ACTIVE','PERSISTENT_CONTEXT_POLICY','PRESET',200,'CENTRAL_2','{"target_id":"CENTRAL_2"}','{"instruction":"A imagem principal central e as duas opções devem ser assets isolados com transparência real. Não usar cena contextual completa com fundo. Pode remover somente fundo simples quando a referência estiver correta. Não criar composição artificial.","metadata":{},"asset_requirements":{"IMAGEM_PRINCIPAL":"transparent_subject","IMAGEM_1":"transparent_option","IMAGEM_2":"transparent_option"}}',50,100,'SYSTEM_SEED',1,'Seed operacional obrigatório dos presets',unixepoch('now')*1000,unixepoch('now')*1000
WHERE NOT EXISTS (SELECT 1 FROM operational_policies WHERE policy_key='PRESET_CENTRAL_2_TRANSPARENT' AND rule_type='PERSISTENT_CONTEXT_POLICY' AND status!='DELETED');

INSERT INTO operational_policies(id,policy_key,name,description,category,status,rule_type,scope_level,propagation_level,preset,condition_json,action_json,priority,confidence,created_by,version,notes,created_at,updated_at)
SELECT 'POL-SEED-FOCO4','PRESET_FOCO_4_TRANSPARENT','Foco + 4 exige transparência','A imagem principal e as quatro opções devem ser assets isolados com transparência real. Não usar cena completa com fundo. Não compor localmente. Quando necessário, remover apenas fundo simples de uma referência semanticamente correta.','OPERATIONAL_CONTEXT','ACTIVE','PERSISTENT_CONTEXT_POLICY','PRESET',200,'FOCO_4','{"target_id":"FOCO_4"}','{"instruction":"A imagem principal e as quatro opções devem ser assets isolados com transparência real. Não usar cena completa com fundo. Não compor localmente. Quando necessário, remover apenas fundo simples de uma referência semanticamente correta.","metadata":{},"asset_requirements":{"IMAGEM_PRINCIPAL":"transparent_subject","IMAGEM_1":"transparent_option","IMAGEM_2":"transparent_option","IMAGEM_3":"transparent_option","IMAGEM_4":"transparent_option"}}',50,100,'SYSTEM_SEED',1,'Seed operacional obrigatório dos presets',unixepoch('now')*1000,unixepoch('now')*1000
WHERE NOT EXISTS (SELECT 1 FROM operational_policies WHERE policy_key='PRESET_FOCO_4_TRANSPARENT' AND rule_type='PERSISTENT_CONTEXT_POLICY' AND status!='DELETED');

INSERT INTO operational_policies(id,policy_key,name,description,category,status,rule_type,scope_level,propagation_level,preset,condition_json,action_json,priority,confidence,created_by,version,notes,created_at,updated_at)
SELECT 'POL-SEED-EMOJI-HINT','PRESET_EMOJI_HINTS_TRANSPARENT','Emoji Quiz — pistas transparentes','As imagens da etapa de pistas não são cenas completas. Devem ser dicas visuais isoladas, simples e reconhecíveis, preferencialmente com transparência real. Cada pista deve representar um elemento útil para a adivinhação.','OPERATIONAL_CONTEXT','ACTIVE','PERSISTENT_CONTEXT_POLICY','PRESET',200,'EMOJI_QUIZ','{"target_id":"EMOJI_QUIZ"}','{"instruction":"As imagens da etapa de pistas não são cenas completas. Devem ser dicas visuais isoladas, simples e reconhecíveis, preferencialmente com transparência real. Cada pista deve representar um elemento útil para a adivinhação.","metadata":{},"asset_requirement":"transparent_hint"}',50,100,'SYSTEM_SEED',1,'Seed operacional obrigatório dos presets',unixepoch('now')*1000,unixepoch('now')*1000
WHERE NOT EXISTS (SELECT 1 FROM operational_policies WHERE policy_key='PRESET_EMOJI_HINTS_TRANSPARENT' AND rule_type='PERSISTENT_CONTEXT_POLICY' AND status!='DELETED');

INSERT INTO operational_policies(id,policy_key,name,description,category,status,rule_type,scope_level,propagation_level,preset,condition_json,action_json,priority,confidence,created_by,version,notes,created_at,updated_at)
SELECT 'POL-SEED-EMOJI-RES4','PRESET_EMOJI_RESULT_4X3','Emoji Quiz — resultado 4:3','A etapa de resultado normalmente pode apresentar uma imagem completa do personagem, obra, objeto ou resposta. Usar imagem 4:3 ou crop-safe para 4:3, salvo política mais específica.','OPERATIONAL_CONTEXT','ACTIVE','PERSISTENT_CONTEXT_POLICY','PRESET',200,'EMOJI_QUIZ','{"target_id":"EMOJI_QUIZ"}','{"instruction":"A etapa de resultado normalmente pode apresentar uma imagem completa do personagem, obra, objeto ou resposta. Usar imagem 4:3 ou crop-safe para 4:3, salvo política mais específica.","metadata":{},"asset_requirement":"result_4x3"}',50,100,'SYSTEM_SEED',1,'Seed operacional obrigatório dos presets',unixepoch('now')*1000,unixepoch('now')*1000
WHERE NOT EXISTS (SELECT 1 FROM operational_policies WHERE policy_key='PRESET_EMOJI_RESULT_4X3' AND rule_type='PERSISTENT_CONTEXT_POLICY' AND status!='DELETED');

INSERT INTO operational_policies(id,policy_key,name,description,category,status,rule_type,scope_level,propagation_level,preset,condition_json,action_json,priority,confidence,created_by,version,notes,created_at,updated_at)
SELECT 'POL-SEED-EMOJI-REVEAL','PRESET_EMOJI_RESULT_REVEAL','Emoji resultado — revelação','A revelação deve apresentar a resposta visual de forma clara. Por padrão, usar raster 4:3/crop-safe; as pistas anteriores continuam sendo transparent_hint.','OPERATIONAL_CONTEXT','ACTIVE','PERSISTENT_CONTEXT_POLICY','PRESET',200,'EMOJI_RESULTADO','{"target_id":"EMOJI_RESULTADO"}','{"instruction":"A revelação deve apresentar a resposta visual de forma clara. Por padrão, usar raster 4:3/crop-safe; as pistas anteriores continuam sendo transparent_hint.","metadata":{},"asset_requirement":"raster_4x3"}',50,100,'SYSTEM_SEED',1,'Seed operacional obrigatório dos presets',unixepoch('now')*1000,unixepoch('now')*1000
WHERE NOT EXISTS (SELECT 1 FROM operational_policies WHERE policy_key='PRESET_EMOJI_RESULT_REVEAL' AND rule_type='PERSISTENT_CONTEXT_POLICY' AND status!='DELETED');

INSERT INTO operational_policies(id,policy_key,name,description,category,status,rule_type,scope_level,propagation_level,preset,condition_json,action_json,priority,confidence,created_by,version,notes,created_at,updated_at)
SELECT 'POL-SEED-FILME-HINT','PRESET_FILME_HINTS_TRANSPARENT','Filme — pistas transparentes','As imagens de pista devem ser elementos visuais isolados e reconhecíveis, não uma cena completa do filme. Preferir assets com transparência real. As pistas devem ajudar o jogador a inferir a obra sem revelar diretamente a resposta.','OPERATIONAL_CONTEXT','ACTIVE','PERSISTENT_CONTEXT_POLICY','PRESET',200,'FILME','{"target_id":"FILME"}','{"instruction":"As imagens de pista devem ser elementos visuais isolados e reconhecíveis, não uma cena completa do filme. Preferir assets com transparência real. As pistas devem ajudar o jogador a inferir a obra sem revelar diretamente a resposta.","metadata":{},"asset_requirement":"transparent_hint"}',50,100,'SYSTEM_SEED',1,'Seed operacional obrigatório dos presets',unixepoch('now')*1000,unixepoch('now')*1000
WHERE NOT EXISTS (SELECT 1 FROM operational_policies WHERE policy_key='PRESET_FILME_HINTS_TRANSPARENT' AND rule_type='PERSISTENT_CONTEXT_POLICY' AND status!='DELETED');

