SELECT 'POL-SEED-FILME-RES4','PRESET_FILME_RESULT_4X3','Filme — resultado 4:3','A etapa de resultado pode apresentar imagem completa da obra/resposta em 4:3 ou crop-safe para 4:3.','OPERATIONAL_CONTEXT','ACTIVE','PERSISTENT_CONTEXT_POLICY','PRESET',200,'FILME','{"target_id":"FILME"}','{"instruction":"A etapa de resultado pode apresentar imagem completa da obra/resposta em 4:3 ou crop-safe para 4:3.","metadata":{},"asset_requirement":"result_4x3"}',50,100,'SYSTEM_SEED',1,'Seed operacional obrigatório dos presets',unixepoch('now')*1000,unixepoch('now')*1000
