SELECT 'POL-SEED-FILME-REVEAL','PRESET_FILME_RESULT_REVEAL','Filme resultado — revelação','A imagem de revelação deve representar claramente o filme/resposta e funcionar em raster 4:3, salvo regra específica do projeto.','OPERATIONAL_CONTEXT','ACTIVE','PERSISTENT_CONTEXT_POLICY','PRESET',200,'FILME_RESULTADO','{"target_id":"FILME_RESULTADO"}','{"instruction":"A imagem de revelação deve representar claramente o filme/resposta e funcionar em raster 4:3, salvo regra específica do projeto.","metadata":{},"asset_requirement":"raster_4x3"}',50,100,'SYSTEM_SEED',1,'Seed operacional obrigatório dos presets',unixepoch('now')*1000,unixepoch('now')*1000
