SELECT 'POL-SEED-GLOBAL-RESULT','RESULT_IMAGE_MUST_BE_VALIDATED_SEPARATELY','Resultado visual passa por QA separado','Imagens de resultado são slots visuais independentes e também passam por QA. Não considerar a pergunta aprovada apenas porque a imagem principal está correta. Quando houver resultado visual, validar referência, enquadramento, formato e compatibilidade com o preset.','OPERATIONAL_CONTEXT','ACTIVE','PERSISTENT_CONTEXT_POLICY','GLOBAL',100,NULL,'{"target_id":"GLOBAL"}','{"instruction":"Imagens de resultado são slots visuais independentes e também passam por QA. Não considerar a pergunta aprovada apenas porque a imagem principal está correta. Quando houver resultado visual, validar referência, enquadramento, formato e compatibilidade com o preset.","metadata":{},"asset_requirement":"result_4x3","applies_to":["IMAGEM_RESULTADO","RESULTADO","RESULT"]}',40,100,'SYSTEM_SEED',1,'Seed operacional obrigatório dos presets',unixepoch('now')*1000,unixepoch('now')*1000
WHERE NOT EXISTS (SELECT 1 FROM operational_policies WHERE policy_key='RESULT_IMAGE_MUST_BE_VALIDATED_SEPARATELY' AND rule_type='PERSISTENT_CONTEXT_POLICY' AND status!='DELETED');

