SELECT 'POL-SEED-GLOBAL-CROP','RASTER_4X3_CROP_ALLOWED','Crop 4:3 permitido quando seguro','Para slots raster_4x3, uma imagem maior ou em proporção diferente pode ser usada quando existir crop seguro para 4:3. O crop é ajuste técnico permitido. Não aceitar crop que corte rosto, sujeito principal, objeto essencial ou torne a composição ruim.','OPERATIONAL_CONTEXT','ACTIVE','PERSISTENT_CONTEXT_POLICY','GLOBAL',100,NULL,'{"target_id":"GLOBAL"}','{"instruction":"Para slots raster_4x3, uma imagem maior ou em proporção diferente pode ser usada quando existir crop seguro para 4:3. O crop é ajuste técnico permitido. Não aceitar crop que corte rosto, sujeito principal, objeto essencial ou torne a composição ruim.","metadata":{}}',40,100,'SYSTEM_SEED',1,'Seed operacional obrigatório dos presets',unixepoch('now')*1000,unixepoch('now')*1000
WHERE NOT EXISTS (SELECT 1 FROM operational_policies WHERE policy_key='RASTER_4X3_CROP_ALLOWED' AND rule_type='PERSISTENT_CONTEXT_POLICY' AND status!='DELETED');

INSERT INTO operational_policies(id,policy_key,name,description,category,status,rule_type,scope_level,propagation_level,preset,condition_json,action_json,priority,confidence,created_by,version,notes,created_at,updated_at)
SELECT 'POL-SEED-GLOBAL-TRANS','TRANSPARENCY_REAL_REQUIRED','Transparência real obrigatória','Quando o slot exigir transparent_subject, transparent_option ou transparent_hint, a transparência deve ser real. Rejeitar checkerboard incorporado, fundo branco fingindo transparência, halo forte, fragmentos de fundo ou bordas contaminadas.','OPERATIONAL_CONTEXT','ACTIVE','PERSISTENT_CONTEXT_POLICY','GLOBAL',100,NULL,'{"target_id":"GLOBAL"}','{"instruction":"Quando o slot exigir transparent_subject, transparent_option ou transparent_hint, a transparência deve ser real. Rejeitar checkerboard incorporado, fundo branco fingindo transparência, halo forte, fragmentos de fundo ou bordas contaminadas.","metadata":{}}',40,100,'SYSTEM_SEED',1,'Seed operacional obrigatório dos presets',unixepoch('now')*1000,unixepoch('now')*1000
WHERE NOT EXISTS (SELECT 1 FROM operational_policies WHERE policy_key='TRANSPARENCY_REAL_REQUIRED' AND rule_type='PERSISTENT_CONTEXT_POLICY' AND status!='DELETED');

