SELECT 'POL-SEED-GLOBAL-NOCOMP','NO_VISUAL_COMPOSITION_FALLBACK','Não fabricar composição como fallback','Quando a representação correta não existir pronta, não montar, combinar, adicionar objetos ou fabricar composição como fallback. Procurar outra referência/candidata ou relinkar.','OPERATIONAL_CONTEXT','ACTIVE','PERSISTENT_CONTEXT_POLICY','GLOBAL',100,NULL,'{"target_id":"GLOBAL"}','{"instruction":"Quando a representação correta não existir pronta, não montar, combinar, adicionar objetos ou fabricar composição como fallback. Procurar outra referência/candidata ou relinkar.","metadata":{}}',40,100,'SYSTEM_SEED',1,'Seed operacional obrigatório dos presets',unixepoch('now')*1000,unixepoch('now')*1000
